export const meta = {
  name: 'work-tickets',
  description: 'Build and verify each open shelf ticket group, one agent per group',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const GRADE = 'grade: bounded · critical no · design - · build cheap=sonnet · verify build=opus · ceremony full · mode workflow (named) · usage unobservable · tiers: defaults'
const VERDICT = { type: 'object', properties: {
  id: {type: 'string'}, passed: {type: 'boolean'}, why: {type: 'string'},
  findings: {type: 'array', items: {type: 'string'}} },
  required: ['id', 'passed', 'why', 'findings'] }
const M = { cheap: 'sonnet', build: 'opus', deep: 'opus' }
const tier = (t, seat) => M[t[seat]] || (() => { throw Error(`${t.id}: no ${seat} tier`) })()
const D = args.design

const results = await pipeline(
  args.items,
  t => agent(`${GRADE}

You are the build seat for task ${t.task} (tickets ${t.id}) in the repo at ${args.repo}.
Read the design file ${D}: its CONSTRAINTS and your task block ${t.task} are your whole spec.
Work test-first: write the tests in your task's new test file, see them fail, implement, see them pass.
Edit ONLY the files in your task's Files list. Do not edit TICKETS.md, do not commit, do not verify other tasks.
Other agents are editing other files in the same tree concurrently; run only your own test file plus tests/test_books.py
(e.g. python -m pytest -q tests/test_books.py <your test file>).
Report: files changed, the exact test command you ran and its result, and any unrelated problems you noticed.`,
    { label: `fix:${t.id}`, phase: 'Fix', model: tier(t, 'fix') }),
  (fix, t) => agent(`${GRADE}

Verify task ${t.task} (tickets ${t.id}: ${t.title}) in ${args.repo} against the design file ${D}
(its CONSTRAINTS and task block ${t.task}). The build agent reports:
${fix}

Independently check: read the changed files, confirm each ticket's behaviour is actually implemented as specified,
that only the task's listed files were touched for this task (other tasks run concurrently on other files — ignore those),
and run python -m pytest -q tests/test_books.py plus the task's own test file yourself. Try at least one edge case of your own
in a python -c one-liner. Do not edit any file. Default passed=false if anything is unproven.
findings: unrelated defects you noticed, each phrased as "someone should edit X so that Y"; empty if none.`,
    { label: `verify:${t.id}`, phase: 'Verify', schema: VERDICT, model: tier(t, 'verify') })
)
return results.map((r, i) => r || { id: args.items[i].id, passed: false, why: 'agent returned null', findings: [] })

